style.css:
@-moz-document domain("roblox.com") {
/* Changes the main website background */
    body, .container-main, .gotham-theme {
        background-image: url("https://images.unsplash.com/photo-1579546929518-9e396f3cc809") !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-position: center !important;
    }

    /* Makes the content boxes slightly see-through so you can see your wallpaper */
    .section-content, .content, .fb-share-button {
        background: rgba(25, 25, 25, 0.75) !important;
        border-radius: 8px !important;
    }
}
